#include "Components.h"
#include <QSvgRenderer>
namespace fg {
QString objectId(QString id){return id.replace('.','_');}
QFrame* createCard(const QString& id,QWidget* p){auto w=new QFrame(p);w->setObjectName(objectId(id));w->setProperty("role","card");return w;}
QPushButton* createButton(const QString& id,const QString& text,ButtonRole role,QWidget* p){auto b=new QPushButton(text,p);b->setObjectName(objectId(id));const QStringList roles={"primary","outline","danger","soft","yellow","quiet","icon"};b->setProperty("role",roles[int(role)]);b->setMinimumHeight(40);b->setCursor(Qt::PointingHandCursor);return b;}
void setSmallButton(QPushButton& b){b.setProperty("size","small");b.setFixedHeight(30);}
void TimerRing::setSnapshot(const FocusSnapshot& s){snapshot_=s;update();}
void TimerRing::paintEvent(QPaintEvent*){QPainter p(this);p.setRenderHint(QPainter::Antialiasing);int d=qMin(width(),height())-24;QRectF r((width()-d)/2.,(height()-d)/2.,d,d);p.setPen(QPen(QColor("#E6EFDF"),16));p.drawEllipse(r);p.setPen(QPen(QColor("#5F9F64"),16,Qt::SolidLine,Qt::RoundCap));double ratio=snapshot_.plannedSeconds?qBound(0.,double(snapshot_.remainingSeconds)/snapshot_.plannedSeconds,1.):0;p.drawArc(r,90*16,-int(360*16*ratio));if(objectName()=="statistics_donut"){p.setPen(QColor("#263E2B"));p.drawText(r,Qt::AlignCenter,property("ratioText").toString());return;}auto f=font();f.setPixelSize(d>190?48:26);f.setBold(true);p.setFont(f);p.setPen(QColor("#263E2B"));p.drawText(r,Qt::AlignCenter,QString("%1:%2").arg(snapshot_.remainingSeconds/60,2,10,QChar('0')).arg(snapshot_.remainingSeconds%60,2,10,QChar('0')));}
void WeekBarChart::setDays(const QVector<DailyFocus>& d){days_=d;update();}
void WeekBarChart::paintEvent(QPaintEvent*){QPainter p(this);p.setRenderHint(QPainter::Antialiasing);p.setPen(QColor("#E5EBDD"));p.drawLine(20,height()-28,width()-10,height()-28);qint64 max=60;for(auto d:days_)max=qMax(max,d.seconds);int count=qMax(7,int(days_.size()));double step=(width()-30.)/count;auto f=font();f.setPixelSize(11);p.setFont(f);for(int i=0;i<days_.size();++i){auto d=days_[i];double h=(height()-56.)*d.seconds/max;QRectF bar(24+i*step,height()-28-h,step*.45,h);p.setPen(Qt::NoPen);p.setBrush(QColor(i==days_.size()-1?"#F6DD8C":"#A9D886"));if(h>0)p.drawRoundedRect(bar,5,5);p.setPen(QColor("#778575"));p.drawText(QRectF(12+i*step,height()-24,step,22),Qt::AlignCenter,d.date.toString("MM/dd"));}}
StateView::StateView(QWidget* p):QWidget(p){auto l=new QVBoxLayout(this);art_=new QLabel;text_=new QLabel;text_->setWordWrap(true);text_->setAlignment(Qt::AlignCenter);text_->setProperty("role","muted");art_->setAlignment(Qt::AlignCenter);l->addWidget(art_);l->addWidget(text_);}
void StateView::setState(const QString& a,const QString& m){art_->setPixmap(QIcon(a).pixmap(56,56));text_->setText(m);}
Sidebar::Sidebar(QWidget* p):QFrame(p){setProperty("role","sidebar");setFixedWidth(200);auto l=new QVBoxLayout(this);l->setContentsMargins(18,26,18,24);l->setSpacing(10);auto logo=new QLabel;logo->setPixmap(QIcon(":/fg/UI_ASSETS/app_logo.svg").pixmap(54,54));l->addWidget(logo);auto brand=new QLabel(QStringLiteral("拾光岛"));brand->setProperty("role","brand");l->addWidget(brand);auto sub=new QLabel("FOCUS GARDEN");sub->setProperty("role","logoText");l->addWidget(sub);l->addSpacing(25);QStringList titles={QStringLiteral("学习总览"),QStringLiteral("任务管理"),QStringLiteral("专注空间"),QStringLiteral("宠物布丁"),QStringLiteral("学习统计"),QStringLiteral("本地音乐"),QStringLiteral("应用设置")};QStringList icons={"dashboard","tasks","focus","pet","statistics","music","settings"};for(int i=0;i<7;++i){auto b=createButton("nav."+icons[i],titles[i],ButtonRole::Quiet);b->setProperty("role","nav");b->setFixedHeight(46);b->setIcon(QIcon(":/fg/UI_ASSETS/icons/ic_"+icons[i]+".svg"));b->setIconSize(QSize(22,22));l->addWidget(b);buttons_<<b;connect(b,&QPushButton::clicked,this,[this,i]{emit pageRequested(PageId(i));});}l->addStretch();auto tip=new QLabel(QStringLiteral("收集每一刻专注\n让小小的坚持生长"));tip->setProperty("role","muted");l->addWidget(tip);}
void Sidebar::select(PageId id){for(int i=0;i<buttons_.size();++i){auto b=buttons_[i];b->setProperty("selected",i==int(id));b->style()->unpolish(b);b->style()->polish(b);}}
TopHeader::TopHeader(QWidget* p):QFrame(p){setProperty("role","header");setFixedHeight(68);auto l=new QHBoxLayout(this);l->setContentsMargins(26,0,26,0);auto title=new QLabel(QStringLiteral("拾光岛  /  把时间留给热爱"));auto local=new QLabel(QStringLiteral("本地运行"));local->setProperty("role","tag");local->setFixedHeight(28);l->addWidget(title);l->addStretch();l->addWidget(local);}
LayoutPage::LayoutPage(AppServices& s,const QString& key,QWidget* p):QWidget(p),services_(s),key_(key){auto l=new QVBoxLayout(this);l->setContentsMargins(22,20,22,24);QFile f(":/layouts/"+key+".json");if(f.open(QIODevice::ReadOnly))l->addWidget(build(QJsonDocument::fromJson(f.readAll()).object()));l->addStretch();}
QWidget* LayoutPage::component(const QString& id)const{return nodes_.value(id);}
QWidget* LayoutPage::build(const QJsonObject& n){QString k=n["kind"].toString(),id=n["id"].toString(),text=n["text"].toString(),role=n["role"].toString();QWidget* w=nullptr;
 if(k=="v"||k=="h"){
  auto frame=new QFrame;w=frame;auto l=k=="v"?static_cast<QBoxLayout*>(new QVBoxLayout(frame)):static_cast<QBoxLayout*>(new QHBoxLayout(frame));int pad=n["padding"].toInt(0);l->setContentsMargins(pad,pad,pad,pad);l->setSpacing(n["gap"].toInt(14));
  for(auto v:n["children"].toArray()){auto child=v.toObject();auto c=build(child);l->addWidget(c,child["stretch"].toInt(0));if(child["align"]=="center")l->setAlignment(c,Qt::AlignCenter);}
  QString dyn=n["dynamic"].toString();if(!dyn.isEmpty()){auto empty=new StateView;empty->setState(":/fg/UI_ASSETS/states/"+QString(dyn=="today"||dyn=="tasks"?"state_empty_tasks.svg":"state_empty_history.svg"),dyn=="today"?QStringLiteral("今天还没有截止任务"):dyn=="tasks"?QStringLiteral("还没有任务，点击新建任务开始吧"):dyn=="detail"?QStringLiteral("选择任务后在这里查看详情"):QStringLiteral("还没有专注记录"));l->addWidget(empty);}
 }else if(k=="label"){auto a=new QLabel(text);a->setWordWrap(true);w=a;if(text.startsWith('@'))bindings_[id]=text;auto f=a->font();if(role=="pageTitle"){f.setPixelSize(27);f.setBold(true);}else if(role=="metric"){f.setPixelSize(28);f.setBold(true);}else if(role=="bannerTitle"){f.setPixelSize(27);f.setBold(true);}else if(role=="cardTitle"||role=="petTitle"){f.setPixelSize(16);f.setBold(true);}a->setFont(f);if(role=="tag"||role=="tagYellow"){a->setSizePolicy(QSizePolicy::Maximum,QSizePolicy::Fixed);a->setFixedHeight(30);a->setAlignment(Qt::AlignCenter);}
 }else if(k=="button"){auto b=createButton(id,text,ButtonRole::Outline);w=b;QString action=n["action"].toString();connect(b,&QPushButton::clicked,this,[this,action]{emit actionRequested(action);});QString icon=n["icon"].toString();if(!icon.isEmpty()){QPixmap pix=QIcon(":/fg/UI_ASSETS/icons/ic_"+icon+".svg").pixmap(20,20);if(role=="primary"){QPainter painter(&pix);painter.setCompositionMode(QPainter::CompositionMode_SourceIn);painter.fillRect(pix.rect(),Qt::white);}b->setIcon(QIcon(pix));}
 }else if(k=="image"){auto a=new QLabel;auto path=":/fg/UI_ASSETS/"+n["src"].toString();a->setPixmap(QIcon(path).pixmap(n["w"].toInt(150),n["h"].toInt(150)));a->setAlignment(Qt::AlignCenter);w=a;
 }else if(k=="combo"){auto c=new QComboBox;for(auto item:n["items"].toArray())c->addItem(item.toString());c->setMinimumHeight(40);w=c;
 }else if(k=="line"){auto a=new QLineEdit;a->setPlaceholderText(n["placeholder"].toString());a->setMinimumHeight(40);w=a;
 }else if(k=="ring"){w=new TimerRing;}
 else if(k=="chart"){w=new WeekBarChart;}
 else if(k=="progress"){auto a=new QProgressBar;a->setTextVisible(false);a->setValue(0);w=a;}
 else if(k=="slider"){auto a=new QSlider(Qt::Horizontal);a->setMaximum(n["max"].toInt(100));a->setValue(n["value"].toInt());w=a;}
 else if(k=="check"){w=new QCheckBox(text);}
 else if(k=="list"){auto a=new QListWidget;a->addItem(QStringLiteral("还没有音乐，点击添加本地音乐开始"));w=a;}
 else if(k=="table"){auto a=new QTableWidget(0,5);a->setHorizontalHeaderLabels({QStringLiteral("日期"),QStringLiteral("任务"),QStringLiteral("有效时长"),QStringLiteral("状态"),QStringLiteral("金币")});a->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);w=a;}
 else w=new QWidget;
 w->setObjectName(objectId(id));nodes_[id]=w;w->setProperty("kind",k);if(!role.isEmpty())w->setProperty("role",role);
 if(n.contains("w"))w->setFixedWidth(n["w"].toInt());if(n.contains("maxW"))w->setMaximumWidth(n["maxW"].toInt());
 if(n.contains("h")){if(k=="v"||k=="h")w->setMinimumHeight(n["compactH"].toInt(n["h"].toInt()));else w->setFixedHeight(n["h"].toInt());}
 if(n.contains("minH"))w->setMinimumHeight(n["minH"].toInt());if(n["hidden"].toBool())w->hide();return w;
}
void LayoutPage::showResult(const OperationResult& r){if(!r.ok)QMessageBox::information(this,QStringLiteral("拾光岛"),r.error.message);}
void LayoutPage::refreshView(){auto stat=services_.statistics();auto pet=services_.pet();
 QHash<QString,QString> values;
 if(stat.ok){auto s=stat.value;values={{"@today",QString::number(s.todaySeconds/60)+QStringLiteral(" 分钟")},{"@total",QString::number(s.totalSeconds/60)+QStringLiteral(" 分钟")},{"@taskRatio",QString("%1 / %2").arg(s.tasks.completed).arg(s.tasks.total)},{"@taskDone",QString::number(s.tasks.completed)},{"@taskCount",QString::number(s.tasks.total)},{"@completion",s.tasks.total?QString::number(s.tasks.completed*100/s.tasks.total)+"%":QStringLiteral("暂无任务")}};for(auto chart:findChildren<WeekBarChart*>())chart->setDays(s.last7Days);}
 if(pet.ok){auto p=pet.value;values["@coins"]=QString::number(p.coins)+QStringLiteral(" 金币");values["@level"]=QString("Lv.%1").arg(p.level);values["@exp"]=QString::number(p.cumulativeExp)+" EXP";values["@mood"]=QStringLiteral("心情 %1 / 100").arg(p.mood);values["@moodValue"]=QString::number(p.mood);values["@petStatus"]=QStringLiteral("Lv.%1  ·  心情 %2  ·  %3 EXP").arg(p.level).arg(p.mood).arg(p.cumulativeExp);values["@expText"]=p.level>=3?QStringLiteral("已满级"):QStringLiteral("累计经验 %1 / %2 EXP").arg(p.cumulativeExp).arg(p.level==1?50:150);}
 for(auto it=bindings_.cbegin();it!=bindings_.cend();++it)if(auto label=qobject_cast<QLabel*>(nodes_[it.key()]))label->setText(values.value(it.value(),QStringLiteral("读取失败")));
 for(auto ring:findChildren<TimerRing*>()){if(ring->objectName()=="statistics_donut"){FocusSnapshot s;s.plannedSeconds=100;s.remainingSeconds=stat.ok&&stat.value.tasks.total?int(stat.value.tasks.completed*100/stat.value.tasks.total):0;ring->setProperty("ratioText",QString::number(s.remainingSeconds)+"%");ring->setSnapshot(s);}else ring->setSnapshot(services_.focus());}
}
}
